/** Contrato que exponía L002R5: los tres procedimientos del EXPORT. */
public interface Registras {
    ResultadoRegistro cargaMovimiento(byte[] datos);   // CARGAMOV1(DATOS) -> RESULT
    ResultadoRegistro cargaSaldos(byte[] datos);       // CARGASALDOS
    ResultadoRegistro controles(byte[] datos);         // CONTROLES
}

@Service
@RequiredArgsConstructor
public class RegistrasService implements Registras, SmartLifecycle {

    private final ControlDiaRepository control;       // L001/CONTROL
    private final RegistrasProperties props;
    private final AtomicBoolean levantaP015 = new AtomicBoolean(true);   // LEVANTA_P015 := TRUE
    private final ReentrantReadWriteLock cambiaFecha = new ReentrantReadWriteLock(); // CAMBIA_FECHA
    private volatile boolean activo;

    /** Bloque externo: LEVANTA antes de FREEZE; BAJA cuando el MCP descongela la librería. */
    @Override public void start() { control.levanta(props.sistema(), props.csi()); activo = true; }
    @Override public void stop()  { control.baja(props.sistema(), props.csi());    activo = false; }
    @Override public boolean isRunning() { return activo; }
    // ...
}

@Override
public ResultadoRegistro cargaMovimiento(byte[] datos) {
    byte[] alog1 = Arrays.copyOf(datos, datos.length);    // REPLACE POINTER(ALOG1) BY DATOS
    byte[] alog2 = Arrays.copyOf(datos, datos.length);    // copia intacta para ERRORES1
    var mov = MovimientoAlog.de(alog1);

    if (mov.sistemaFan() == props.sistema()) {
        mov = mapeador.aFormatoNuevo(mov);                // MAPEO
    }
    if (!props.sistemasSinNormalizarCaja().contains(props.sistema())) {   // 500, 403, 404
        mov = mov.conCampoDigitos(262, 5, 2).conCampoDigitos(267, 5, 2); // offsets en dígitos de 4 bits
    }

    cambiaFecha.readLock().lock();                         // WHILE LOCKSTATUS(CAMBIA_FECHA) ... WAIT
    try {
        if (mov.sistema() != props.sistema()) {
            avisos.postea("SISTEMA NO HABILITADO EN S151, SISTEMA : %04d".formatted(mov.sistema()));
            return registraError(alog2, ResultadoRegistro.SISTEMA_NO_HABILITADO);   // RESULT := 1
        }
        return procesa(mov, alog2);
    } finally {
        cambiaFecha.readLock().unlock();
    }
}

/** Devuelve el índice de día (NUMDIAC1) y si la fecha contable es válida (RESULT 0 o 4). */
DiaContable ubicaDia(LocalDate fecContable) {
    boolean equipoPruebas = props.equiposPruebas().contains(props.nombreEquipo()); // ACYPBETA, VDMBETA
    if (!equipoPruebas && fecContable.equals(control.fechaProceso())) {
        return DiaContable.valido(control.diaSemana());
    }
    if (equipoPruebas || fecContable.isAfter(control.fechaProceso())) {
        List<LocalDate> fecDia = control.fechasDia();          // FEC_DIA[0..9]
        int idx = fecDia.indexOf(fecContable);
        if (idx >= 0) return DiaContable.valido(idx);
    }
    // Fecha anterior a la de proceso o no encontrada: RESULT := 4, se usa el día de la semana
    avisos.postea("FECHA CONTABLE NO VALIDA, FECHA : " + fecContable.format(BASIC_ISO_DATE));
    return DiaContable.invalido(control.diaSemana());
}

ResultadoRegistro procesa(MovimientoAlog mov, byte[] alog2) {
    DiaContable dia = ubicaDia(mov.fechaContable());
    int funcion = mov.funcion();                            // FUNCIONVAL
    // RESULT 4 (fecha no válida) NO detiene el despacho: la función se ejecuta sobre el día de la semana.
    Runnable accion = switch (funcion) {
        case 1      -> () -> cargaMemoria(mov, dia);        // CARGAMEMORY
        case 2      -> () -> elimina(mov, dia);             // ELIMINA
        case 11     -> () -> inicia(mov, dia);
        case 12     -> () -> termina(mov, dia);
        case 21     -> () -> eliminaPorProceso(mov, dia);   // ELIMXPROC
        case 22     -> () -> eliminaPorAutorizacion(mov, dia); // ELIMXAUT
        case 31, 32 -> () -> rebloquea(dia);                // REBLOCKADE
        case 97     -> () -> prefinal(dia);
        case 98     -> () -> fin(dia);
        default     -> null;
    };
    if (accion == null) {
        avisos.postea("FUNCION NO VALIDA, FUNCION : %02d".formatted(funcion));
        return registraError(alog2, ResultadoRegistro.FUNCION_NO_VALIDA);   // RESULT := 2, GRABAMOV := FALSE
    }
    accion.run();
    if (dia.valido()) lanzador.evalua(mov, dia, funcion);   // P015, P016, P025
    return cierra(mov, dia.valido() ? ResultadoRegistro.OK : ResultadoRegistro.FECHA_NO_VALIDA, alog2);
}

@Component
@RequiredArgsConstructor
public class LanzadorProcesos {

    private final JobLauncher launcher;
    private final Job p015, p016, p025;
    private final EstadoProcesos estado;          // STATUS_MIX_P015/P016 por día, STATUS_MIX_P025, STATUS_BDSDO
    private final LogDiarioRepository logs;
    private final ControlDiaRepository control;   // FEC_CON, FECS151
    private final AtomicBoolean levantaP015;      // compartido con RegistrasService
    private final RegistrasProperties props;      // hora-corte-p016: 20:00:00 · tipo-proceso-intradia-max: 15
    private final Clock clock;

    void evalua(MovimientoAlog mov, DiaContable dia, int funcion) {
        LocalTime hora = LocalTime.now(clock);
        boolean p015Libre = estado.p015(dia) < 1;
        boolean p016Libre = estado.p016(dia) < 1 && hora.isBefore(props.horaCorteP016());
        boolean intradia  = mov.tipoProceso() <= props.tipoProcesoIntradiaMax();   // IDFTIPPROC < 16

        if (funcion < 98 && (p015Libre || p016Libre)
                && !logs.fecha(dia).isBefore(control.fechaContableControl())     // FEC_DIA >= FEC_CON
                && intradia && levantaP015.get()) {
            logs.rebloqueaParaLectura(dia);       // CLOSE LOCK, BLOCKSIZE 150/90, SYNCHRONIZE OUT
            if (p015Libre) lanza(p015, dia);      // VERSION_P015 + WAIT((3)) + EXTERNO_P015
            if (p016Libre) lanza(p016, dia);
        }
        if (estado.p025() < 1 && logs.fecha(dia).equals(control.fechaS151()) && funcion == 1
                && !intradia && estado.baseSaldos() < 99) {                       // 99 = base SDO cerrada
            lanza(p025, dia);
        }
    }

    private void lanza(Job job, DiaContable dia) {
        // VERSION_Pxxx y WAIT((3)) eran el apretón de manos de versión; aquí lo resuelve el JobRepository.
        launcher.run(job, new JobParametersBuilder()
                .addLocalDate("fechaDia", logs.fecha(dia)).addLong("ts", System.nanoTime()).toJobParameters());
    }
}

@Slf4j
@Repository
@RequiredArgsConstructor
public class LogDiarioRepository {

    private final JdbcTemplate jdbc;
    private final ValidadorDf validador;          // DFVALIDA
    private final ControlDiaRepository control;   // L001/CONTROL
    private final RegistrasProperties props;

    /** CARGAMEMORY: función 1 valida; si procede, graba en LOG y DES del día. */
    @Transactional
    public boolean cargaMemoria(MovimientoAlog mov, DiaContable dia, boolean grabaMov) {
        if (mov.funcion() == 1) validador.valida(mov, mov.sistema(), mov.producto());
        if (!grabaMov) return false;
        jdbc.update("INSERT INTO s151_log_dia (fecha_dia, nivel, registro) VALUES (?, nextval('s151_log_seq'), ?)",
                    fecha(dia), mov.bytes());
        // DFAMPLIAFILE (+20000 registros LOG, +5000 DES cuando quedan menos de 5) desaparece:
        // una tabla no tiene tamaño preasignado.
        return true;
    }

    /** ACTNIVEL: publica el nivel alcanzado en L001/CONTROL. */
    public void actualizaNivel(DiaContable dia) {
        int r = control.consisDia(8, props.sistema(), props.csi(), fecha(dia), nivel(dia));
        if (r > 0) log.error("ERROR LIB/REGISTRAS {} RESULT L001/CONTROL {}", props.sistema(), r);  // en el fuente está comentado
    }
}

private final AtomicInteger actNivel = new AtomicInteger();    // ACT_NIVEL

ResultadoRegistro cierra(MovimientoAlog mov, ResultadoRegistro r, byte[] alog2) {
    if (r.esCero() || r == ResultadoRegistro.FECHA_NO_VALIDA) {
        boolean altaOBaja = mov.funcion() == 1 || mov.funcion() == 2;
        if (!altaOBaja || actNivel.incrementAndGet() >= props.cadaCuantosNivel()) {   // 1000
            actNivel.set(0);
            logs.actualizaNivel(diaDe(mov));
        }
    }
    if (!r.esCero()) {
        // Se graba la copia original (ALOG2) con el código de resultado en el offset 1078.
        errores.graba(MovimientoAlog.conResultado(alog2, r.codigo()));   // WRITE(ERRORES1[NIVERROR1],90,ALOG2)
    }
    return r.conDatos(mov.bytes());     // REPLACE DATOS BY POINTER(ALOG1) FOR SIZEDATC1
}

@Component
public class MapeadorFormatoNuevo {

    /** Campo destino: origen en ALOG1 (offset en dígitos de 4 bits) o relleno constante. */
    sealed interface Campo permits Copia, Relleno {}
    record Copia(String nombre, int offset, int largo) implements Campo {}
    record Relleno(String nombre, char valor, int largo) implements Campo {}

    /** Orden y tamaños exactos de REPLACE POINTER(BLOG1,4) BY ... en MAPEO. */
    static final List<Campo> FORMATO_NUEVO = List.of(
        new Copia("FUNCION", -1, 2),                 // IDFFUNCION(ALOG1) FOR 2 DIGITS
        new Relleno("FORMATO", '0', 2),
        new Copia("SIST", 2, 4), new Copia("PROD", 6, 4), new Copia("INS", 10, 2),
        new Relleno("SERVICIO", '0', 2), new Relleno("TIPO_OPER", ' ', 2),
        // ... 90 campos más, generados desde el fuente, no a mano ...
        new Relleno("REFCLIENTE", ' ', 32),          // el formato nuevo los trae vacíos
        new Relleno("REF1_CTE", ' ', 70), new Relleno("REF2_CTE", ' ', 70),
        new Relleno("REF3_CTE", ' ', 70), new Relleno("REF4_CTE", ' ', 70),
        new Copia("LYENDA1", 630, 80), new Copia("LYENDA2", 710, 80), new Copia("LYENDA3", 790, 80),
        new Copia("LYENDA4", 870, 80), new Copia("LYENDA5", 950, 80));

    public MovimientoAlog aFormatoNuevo(MovimientoAlog mov) {
        var destino = new NibbleBuffer(165 * 12);    // 165 palabras de 48 bits = 1980 dígitos
        for (Campo c : FORMATO_NUEVO) {
            switch (c) {
                case Copia k   -> destino.append(k.offset() < 0 ? mov.funcionDigitos() : mov.nibbles(k.offset(), k.largo()));
                case Relleno r -> destino.fill(r.valor(), r.largo());
            }
        }
        return MovimientoAlog.de(destino.toBytes());
    }
}
